import test from 'node:test';
import assert from 'node:assert/strict';
import {chooseRoute,visibleModels} from '../src/model-policy.js';
test('local namespace retained without upstream',()=>assert.equal(chooseRoute('chatgpt-web/a',{mode:'selected',models:[]},false),'local'));
test('unavailable upstream denied',()=>assert.equal(chooseRoute('m',{mode:'all'},false),'deny'));
test('all nonlocal may route',()=>assert.equal(chooseRoute('unknown',{mode:'all'},true),'upstream'));
test('regex route exact case',()=>{assert.equal(chooseRoute('GPT-x',{mode:'regex',pattern:'^gpt-'},true),'deny');assert.equal(chooseRoute('gpt-x',{mode:'regex',pattern:'^gpt-'},true),'upstream');});
test('selected rejects unchosen',()=>assert.equal(chooseRoute('b',{mode:'selected',models:['a']},true),'deny'));
test('missing catalog preserves saved selection and request',()=>{const f={mode:'selected',models:['a','absent']};assert.deepEqual(visibleModels(['chatgpt-web/a'],['a','b','chatgpt-web/evil'],f),['chatgpt-web/a','a']);assert.deepEqual(f.models,['a','absent']);assert.equal(chooseRoute('absent',f,true),'upstream');});
test('regex catalog and direct request agree',()=>{const f={mode:'regex',pattern:'^m-'};assert.deepEqual(visibleModels(['chatgpt-web/a'],['m-a','other','m-a'],f),['chatgpt-web/a','m-a']);assert.equal(chooseRoute('other',f,true),'deny');});
